questions.prompt:
Here is a ring lookup. Assume `ring` is sorted by `pos`. Find the bug(s).

```js
function getNode(ring, key) {
  const h = hash(key);
  let lo = 0, hi = ring.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (ring[mid].pos < h) lo = mid + 1;
    else hi = mid;
  }
  return ring[lo].node;
}
```

questions.answer:
Keys with `h` greater than the last point go to the last point instead of wrapping to the first.
```js
function getNode(ring, key) {
  if (ring.length === 0) return undefined;
  const h = hash(key);
  let lo = 0, hi = ring.length;          // allow 'past the end'
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (ring[mid].pos < h) lo = mid + 1;
    else hi = mid;
  }
  return ring[lo % ring.length].node;    // wrap around
}
```
